cat > "$EXT/sw.js" <<'JSSW'
// Module service worker. Probes: importScripts() in a module SW, and dynamic import().
// NOTE: `typeof import` would be a SyntaxError here (module context reserves `import`),
// so the dynamic-import probe has to be a real runtime call.
let importScriptsResult = 'not-attempted';
try {
  importScripts('nonexistent.js');
  importScriptsResult = 'unexpected-success';
} catch (e) {
  importScriptsResult = `${e.name}: ${e.message}`;
}

let dynamicImportResult = 'pending';
(async () => {
  try {
    const m = await import('./mod.js');
    dynamicImportResult = `ok → ${m.hello()}`;
  } catch (e) {
    dynamicImportResult = `${e.name}: ${e.message}`;
  }
})();

chrome.action.onClicked.addListener(() => {
  chrome.tabs.create({ url: chrome.runtime.getURL('page.html') });
});

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  if (msg && msg.type === 'sw-probe') {
    sendResponse({
      importScriptsResult,
      dynamicImportResult,
      swWorkerCtor: typeof Worker,
      swSharedWorkerCtor: typeof SharedWorker,
      swChrome: typeof chrome
    });
    return true;
  }
  return false;
});
JSSW

cat > "$EXT/worker.js" <<'JSWORKER'
// Dedicated module worker. Answers capability probes and does the heavy parse.
// Dynamic import() is probed at runtime — `typeof import` is a SyntaxError in module scope.
let dynamicImportResult = 'pending';
(async () => {
  try {
    const m = await import('./mod.js');
    dynamicImportResult = `ok → ${m.hello()}`;
  } catch (e) {
    dynamicImportResult = `${e.name}: ${e.message}`;
  }
})();

self.addEventListener('message', (e) => {
  const d = e.data || {};

  if (d.type === 'ping') {
    self.postMessage({
      pong: true,
      workerChrome: typeof chrome,
      workerWorkerCtor: typeof Worker,
      workerSharedWorkerCtor: typeof SharedWorker,
      workerDynamicImport: dynamicImportResult
    });
    return;
  }

  // Transfer-cost probe: clone in + clone out, no parsing.
  if (d.type === 'echo') {
    self.postMessage({ id: d.id, len: (d.text || '').length });
    return;
  }

  // The real benchmark: JSON.parse + full node count.
  if (d.type === 'parse-count') {
    const t0 = performance.now();
    let value = null;
    let err = null;
    try {
      value = JSON.parse(d.text);
    } catch (ex) {
      err = `${ex.name}: ${ex.message}`;
    }
    const parseMs = performance.now() - t0;

    let nodes = 0;
    if (!err) {
      const stack = [value];
      while (stack.length) {
        const x = stack.pop();
        nodes++;
        if (x && typeof x === 'object') {
          if (Array.isArray(x)) {
            for (let i = 0; i < x.length; i++) stack.push(x[i]);
          } else {
            for (const k in x) if (Object.prototype.hasOwnProperty.call(x, k)) stack.push(x[k]);
          }
        }
      }
    }

    self.postMessage({
      id: d.id,
      ms: parseMs,
      err,
      nodes,
      topKeys: value && typeof value === 'object' && !Array.isArray(value) ? Object.keys(value) : []
    });
  }
});
JSWORKER

cat > "$EXT/sworker.js" <<'JSSHARED'
// SharedWorker probe.
self.onconnect = (e) => {
  const port = e.ports[0];
