cat > "$EXT/page.js" <<'JSPAGE'
/* Turbo JSON Spike page logic. External file only — inline scripts are dead under MV3 CSP. */
const $ = (id) => document.getElementById(id);
const out = $('out');
const logEl = $('log');
const lines = [];
let worker = null;

function rec(id, status, detail) {
  const line = `[${id}] ${status} :: ${detail}`;
  lines.push(line);
  out.value = lines.join('\n');
  const div = document.createElement('div');
  div.textContent = line;
  div.className = status === 'PASS' ? 'p' : status === 'FAIL' ? 'f' : status === 'OBS' ? 'o' : 'i';
  logEl.appendChild(div);
  logEl.scrollTop = logEl.scrollHeight;
}

function heap() {
  return performance.memory
    ? `${(performance.memory.usedJSHeapSize / 1048576).toFixed(0)}MB used / ${(performance.memory.jsHeapSizeLimit / 1048576).toFixed(0)}MB limit`
    : 'performance.memory n/a';
}

// Every CSP refusal lands here with the exact directive — a thing we must capture verbatim.
document.addEventListener('securitypolicyviolation', (e) => {
  rec('csp-violation', 'OBS', `directive=${e.violatedDirective} blockedURI=${e.blockedURI} source=${e.sourceFile}:${e.lineNumber} disposition=${e.disposition}`);
});

function spawnWorker() {
  return new Worker(chrome.runtime.getURL('worker.js'), { type: 'module' });
}

async function testCspEval() {
  try {
    const v = eval('1+1');
    rec('csp-eval', 'FAIL', `eval() SUCCEEDED (=${v}) — CSP is not blocking it!`);
  } catch (e) {
    rec('csp-eval', 'PASS', `eval() blocked: ${e.name}: ${e.message}`);
  }
  try {
    const f = new Function('return 1');
    rec('csp-new-function', 'FAIL', `new Function() SUCCEEDED (=${f()}) — CSP is not blocking it!`);
  } catch (e) {
    rec('csp-new-function', 'PASS', `new Function() blocked: ${e.name}: ${e.message}`);
  }
}

async function testWorkerPackageFile() {
  try {
    const w = spawnWorker();
    const t = performance.now();
    const reply = await new Promise((res, rej) => {
      const to = setTimeout(() => rej(new Error('timeout after 3s')), 3000);
      w.onmessage = (e) => { clearTimeout(to); res(e.data); };
      w.onerror = (e) => { clearTimeout(to); rej(new Error('onerror: ' + (e.message || 'unknown'))); };
      w.postMessage({ type: 'ping' });
    });
    worker = w;
    rec('worker-package-file', 'PASS',
      `module Worker from chrome.runtime.getURL created; ping→pong in ${(performance.now() - t).toFixed(1)}ms`);
    rec('worker-chrome-api', 'OBS', `inside worker: typeof chrome=${reply.workerChrome}, typeof Worker=${reply.workerWorkerCtor}, typeof SharedWorker=${reply.workerSharedWorkerCtor}, dynamic import → ${reply.workerDynamicImport}`);
  } catch (e) {
    rec('worker-package-file', 'FAIL', `${e.name}: ${e.message}`);
  }
}

async function testWorkerBlob() {
  try {
    const url = URL.createObjectURL(new Blob(['self.onmessage=()=>self.postMessage("blob-ok")'], { type: 'text/javascript' }));
    const w = new Worker(url);
    const r = await new Promise((res, rej) => {
      const to = setTimeout(() => rej(new Error('timeout after 2s')), 2000);
      w.onmessage = (e) => { clearTimeout(to); res(e.data); };
      w.onerror = (e) => { clearTimeout(to); rej(new Error('onerror: ' + (e.message || 'unknown'))); };
    });
    rec('worker-blob-url', 'OBS', `blob: Worker ALLOWED (research predicted blocked) → ${r}`);
  } catch (e) {
    rec('worker-blob-url', 'OBS', `blob: Worker blocked (as predicted): ${e.name}: ${e.message}`);
  }
}

async function testSharedWorker() {
  try {
    const sw = new SharedWorker(chrome.runtime.getURL('sworker.js'));
    const r = await new Promise((res, rej) => {
      const to = setTimeout(() => rej(new Error('timeout after 2s')), 2000);
      sw.port.onmessage = (e) => { clearTimeout(to); res(e.data); };
      sw.port.start();
      sw.port.postMessage('ping');
    });
    rec('shared-worker', 'OBS', `SharedWorker from package file works → ${r}`);
  } catch (e) {
    rec('shared-worker', 'OBS', `SharedWorker failed: ${e.name}: ${e.message}`);
