}

async function testDynamicImport() {
  try {
    const m = await import(chrome.runtime.getURL('mod.js'));
    rec('dynamic-import', m.hello() === 'hello-from-mod' ? 'PASS' : 'FAIL',
      `import(chrome.runtime.getURL('mod.js')) resolved → ${m.hello()}`);
  } catch (e) {
    rec('dynamic-import', 'FAIL', `dynamic import failed: ${e.name}: ${e.message}`);
