}

async function testServiceWorker() {
  try {
    const r = await chrome.runtime.sendMessage({ type: 'sw-probe' });
    rec('sw-probe', 'PASS', `SW answered; typeof chrome=${r.swChrome}`);
    rec('sw-module-importScripts', 'OBS', `module SW importScripts() → ${r.importScriptsResult}`);
    rec('sw-dynamic-import', 'OBS', `module SW dynamic import() → ${r.dynamicImportResult}`);
    rec('sw-worker-ctor', 'OBS', `inside SW: typeof Worker=${r.swWorkerCtor}, typeof SharedWorker=${r.swSharedWorkerCtor}`);
  } catch (e) {
    rec('sw-probe', 'FAIL', `${e.name}: ${e.message} (is the extension reloaded?)`);
