async function testStorage() {
  try {
    await chrome.storage.session.set({ spike: 'v1' });
    const got = await chrome.storage.session.get('spike');
    const used = await chrome.storage.session.getBytesInUse(null);
    rec('storage-session', got.spike === 'v1' ? 'PASS' : 'FAIL', `session set/get ok, bytesInUse=${used}`);
  } catch (e) {
    rec('storage-session', 'FAIL', `${e.name}: ${e.message}`);
  }
  try {
    const used = await chrome.storage.local.getBytesInUse(null);
    rec('storage-quota', 'OBS', `local.QUOTA_BYTES=${chrome.storage.local.QUOTA_BYTES} local.bytesInUse=${used}`);
  } catch (e) {
