async function testI18n() {
  const name = chrome.i18n.getMessage('extName');
  const lang = chrome.i18n.getUILanguage();
  const accept = await chrome.i18n.getAcceptLanguages();
  rec('i18n', name ? 'PASS' : 'FAIL', `getMessage('extName')="${name}" uiLanguage=${lang} acceptLanguages=${accept.join(',')}`);
  rec('i18n-default-locale', 'OBS', `default_locale=en；浏览器 UI 语言 ${lang} 时扩展名显示为「${name}」，据此判断回退行为`);
}

async function runAll() {
  rec('env', 'INFO', `ua=${navigator.userAgent}`);
  rec('env', 'INFO', `heap=${heap()} cores=${navigator.hardwareConcurrency} deviceMemory=${navigator.deviceMemory ?? 'n/a'}`);
  rec('env', 'INFO', `crossOriginIsolated=${self.crossOriginIsolated}`);
  await testCspEval();
  await testWorkerPackageFile();
  await testWorkerBlob();
  await testSharedWorker();
  await testDynamicImport();
  await testServiceWorker();
  await testStorage();
  await testI18n();
  rec('manual-remaining', 'INFO',
    '还需手动：写剪贴板（手势/无手势）、读剪贴板、粘贴框 Cmd+V、手动选文件、程序化选择器、拖放、大样本基准');
}

function benchNextPaint() {
  return new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res)));
}

async function askWorker(payload, timeoutMs) {
  if (!worker) worker = spawnWorker();
  const w = worker;
  const id = 'q' + Math.random().toString(36).slice(2);
  return await new Promise((res, rej) => {
    const to = setTimeout(() => rej(new Error(`worker timeout after ${timeoutMs}ms`)), timeoutMs);
    const onMsg = (e) => {
      if (e.data && e.data.id === id) {
        clearTimeout(to);
        w.removeEventListener('message', onMsg);
        res(e.data);
      }
    };
    w.addEventListener('message', onMsg);
    w.postMessage({ ...payload, id });
  });
}

async function runBench(text, label, sourceMs) {
  const bytes = new Blob([text]).size;
  const t0 = performance.now();
  rec(`bench-${label}-input`, 'OBS',
    `来源=${label} 字节=${bytes} (${(bytes / 1048576).toFixed(2)}MB) 字符=${text.length} 拿到文本耗时=${sourceMs.toFixed(0)}ms`);

  // (a) transfer-only round trip: isolate structured-clone cost
  try {
    const tt = performance.now();
    await askWorker({ type: 'echo', text }, 180000);
    rec(`bench-transfer-${label}`, 'OBS',
      `仅传输往返（clone 进+出，不解析）=${(performance.now() - tt).toFixed(1)}ms`);
  } catch (e) {
    rec(`bench-transfer-${label}`, 'FAIL', `${e.name}: ${e.message}`);
  }

  // (b) parse + count inside the worker, then first paint of a trivial render
  try {
    const tp = performance.now();
    const r = await askWorker({ type: 'parse-count', text }, 300000);
    const roundTrip = performance.now() - tp;
    $('summary').textContent =
      `${label}: ${(bytes / 1048576).toFixed(2)}MB · worker parse ${r.ms.toFixed(1)}ms · nodes ${r.nodes} · topKeys ${JSON.stringify(r.topKeys)}`;
    await benchNextPaint();
    const total = performance.now() - t0;
    rec(`bench-${label}`, r.err ? 'FAIL' : 'PASS',
      `worker_parse_ms=${r.ms.toFixed(1)} nodes=${r.nodes} postMessage_roundtrip_ms=${roundTrip.toFixed(1)}` +
      ` paint_after_parse_ms=${(total - roundTrip).toFixed(1)} total_to_first_paint_ms=${total.toFixed(1)} heap=${heap()}` +
      (r.err ? ` parse_error=${r.err}` : ''));
    rec(`bench-${label}-keys`, 'OBS', `顶层键=${JSON.stringify(r.topKeys)}`);
  } catch (e) {
    rec(`bench-${label}`, 'FAIL', `${e.name}: ${e.message}`);
  }
}

// ── clipboard ────────────────────────────────────────────────────────────
$('clip-gesture').addEventListener('click', async () => {
  try {
    await navigator.clipboard.writeText('turbo-spike-ok');
    rec('clipboard-write-gesture', 'PASS',
      'writeText() inside a click handler SUCCEEDED with zero clipboard permissions declared');
  } catch (e) {
    rec('clipboard-write-gesture', 'FAIL', `${e.name}: ${e.message}`);
  }
});

$('clip-nogesture').addEventListener('click', () => {
  setTimeout(async () => {
    try {
      await navigator.clipboard.writeText('turbo-spike-nogesture');
      rec('clipboard-write-nogesture', 'OBS', 'writeText() without a user gesture SUCCEEDED (unexpected)');
    } catch (e) {
      rec('clipboard-write-nogesture', 'OBS', `writeText() without a gesture rejected: ${e.name}: ${e.message}`);
    }
  }, 1500);
});

$('clip-read').addEventListener('click', async () => {
  try {
    const t = await navigator.clipboard.readText();
    rec('clipboard-read', 'OBS', `readText() SUCCEEDED without clipboardRead (len=${t.length}) — negative control failed`);
  } catch (e) {
    rec('clipboard-read', 'OBS', `readText() rejected (expected): ${e.name}: ${e.message}`);
  }
});

// The product's real import path: clipboard → JS memory → Worker. No DOM text node,
// no textarea. (Pasting a big document into a <textarea> hangs the main thread for
// tens of seconds — that artifact must never enter our numbers.)
$('clip-import').addEventListener('click', async () => {
  const t0 = performance.now();
  let text = '';
  try {
    text = await navigator.clipboard.readText();
  } catch (e) {
    rec('clip-import-read', 'FAIL', `readText() failed: ${e.name}: ${e.message}（剪贴板里有没有内容？）`);
    return;
  }
  const readMs = performance.now() - t0;
  rec('clip-import-read', 'PASS', `readText() 拿到 ${text.length} 字符 / ${(new Blob([text]).size / 1048576).toFixed(2)}MB，耗时 ${readMs.toFixed(1)}ms`);
  if (text.length < 200000) {
    warn(`剪贴板内容只有 ${text.length} 字符——基准需要大样本，请先让向导把 10MB 样本放进剪贴板。`);
    return;
  }
  runBench(text, `clip-${(new Blob([text]).size / 1048576).toFixed(1)}mb`, readMs);
});

// ── file input ───────────────────────────────────────────────────────────
$('pick').addEventListener('click', () => $('file').click());
$('file').addEventListener('change', async (e) => {
  const f = e.target.files[0];
  if (!f) return;
  const t = performance.now();
  const txt = await f.text();
  rec('file-input-manual', 'PASS',
    `picked ${f.name} ${(f.size / 1048576).toFixed(2)}MB → read ${txt.length} chars in ${(performance.now() - t).toFixed(0)}ms (no permission prompt expected)`);
});
$('pick-prog').addEventListener('click', () => {
  try {
    $('file2').click();
    rec('programmatic-file-picker', 'OBS', 'input.click() called without a direct user activation — 观察选择器是否弹出');
  } catch (e) {
    rec('programmatic-file-picker', 'OBS', `input.click() threw: ${e.name}: ${e.message}`);
  }
});
$('file2').addEventListener('change', (e) => {
  const f = e.target.files[0];
  if (f) rec('programmatic-file-picker', 'OBS', `picker DID open and picked ${f.name} (${(f.size / 1048576).toFixed(2)}MB)`);
});

// ── drag & drop ──────────────────────────────────────────────────────────
const drop = $('drop');
drop.addEventListener('dragover', (e) => { e.preventDefault(); drop.classList.add('over'); });
drop.addEventListener('dragleave', () => drop.classList.remove('over'));
drop.addEventListener('drop', async (e) => {
  e.preventDefault();
  drop.classList.remove('over');
  const f = e.dataTransfer && e.dataTransfer.files[0];
  if (!f) { rec('drop-read', 'FAIL', 'drop event had no file in dataTransfer'); return; }
  const t = performance.now();
  const txt = await f.text();
  const ms = performance.now() - t;
  rec('drop-read', 'PASS', `dropped ${f.name} ${(f.size / 1048576).toFixed(2)}MB → ${txt.length} chars in ${ms.toFixed(0)}ms`);
  if (txt.length > 200000) runBench(txt, `drop-${(f.size / 1048576).toFixed(0)}mb`, ms);
});

// ── paste ────────────────────────────────────────────────────────────────
$('paste').addEventListener('paste', async (e) => {
  // Read the text straight off the event (~1ms) and preventDefault so Chrome never
  // inserts it into the textarea. Without preventDefault, pasting ~10MB hangs the
  // main thread for ~40s — the cost is *rendering* the giant text node, not the paste
  // event itself. This is exactly the pattern the product's paste-to-import must use.
  const text = e.clipboardData ? e.clipboardData.getData('text') : '';
  e.preventDefault();
  const t = performance.now();
  rec('paste-event', text ? 'PASS' : 'FAIL', `paste event fired, clipboardData len=${text.length}（已 preventDefault，文本未进入 DOM）`);
  if (!text) return;
  if (text.length > 200000) {
    runBench(text, `paste-${(text.length / 1048576).toFixed(1)}mb`, performance.now() - t);
  }
});

// ── results export (also the <a download> no-permission probe) ────────────
$('copy').addEventListener('click', async () => {
  try {
    await navigator.clipboard.writeText(out.value);
    rec('copy-results', 'PASS', 'copied the result block via clipboard.writeText()');
  } catch (e) {
    rec('copy-results', 'FAIL', `${e.name}: ${e.message} — 请手动全选文本框复制`);
    out.focus();
    out.select();
  }
});

$('download').addEventListener('click', () => {
  try {
    const blob = new Blob([out.value], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'turbo-spike-results.txt';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 5000);
    rec('download-no-permission', 'OBS', '<a download> clicked with no downloads permission — 检查 ~/Downloads/turbo-spike-results.txt 是否落盘');
  } catch (e) {
    rec('download-no-permission', 'OBS', `download failed: ${e.name}: ${e.message}`);
  }
});

$('run').addEventListener('click', () => { runAll(); });
