cat > "$SPIKE/gen-samples.js" <<'GENJS'
// Generates synthetic JSON samples. usage: node gen-samples.js <outDir> [mb,mb,...]
const fs = require('fs');
const path = require('path');

const outDir = process.argv[2];
const sizesArg = process.argv[3] || '2,10,50';
fs.mkdirSync(outDir, { recursive: true });

function record(i) {
  return {
    id: 'ID' + (1000000 + i),
    hotel_id: i % 99991,
    name: 'Hotel ' + (i % 9973) + ' 海景房 Seaview',
    price: 100 + (i % 900) + (i % 7) / 10,
    currency: 'CNY',
    rating: (i % 50) / 10,
    city: 'City' + (i % 317),
    address: 'Aabaadhee Hingun Road ' + i,
    tags: ['tag' + (i % 13), 'tag' + (i % 7), 'tag' + (i % 101)],
    active: i % 3 === 0,
    desc: '描述文本 description ' + i,
    updated: '2026-0' + (1 + (i % 9)) + '-1' + (i % 9)
  };
}

function generate(targetBytes, file) {
  const fd = fs.openSync(file, 'w');
  const head = '{"status":{"code":0,"msg":"SUCCESS"},"data":{"items":[';
  fs.writeSync(fd, head);
  let written = Buffer.byteLength(head, 'utf8');
  let i = 0;
  let first = true;
  let buf = [];
  let bufBytes = 0;
  // Judge on written+bufBytes: `written` alone lags behind the buffered tail,
  // which made every target overshoot to one full buffer's worth.
  while (written + bufBytes < targetBytes) {
    const piece = (first ? '' : ',') + JSON.stringify(record(i++));
    first = false;
    buf.push(piece);
    bufBytes += Buffer.byteLength(piece, 'utf8');
    if (bufBytes > (1 << 18)) {
      fs.writeSync(fd, buf.join(''));
      written += bufBytes;
      buf = [];
      bufBytes = 0;
    }
  }
  fs.writeSync(fd, buf.join(''));
  written += bufBytes;
  fs.writeSync(fd, ']}}');
  fs.closeSync(fd);
  return fs.statSync(file).size;
}

for (const mb of sizesArg.split(',')) {
  const size = parseFloat(mb);
  const file = path.join(outDir, `${mb}mb.json`);
  const t = Date.now();
  const bytes = generate(Math.round(size * 1048576), file);
  console.log(`${path.basename(file)}  ${(bytes / 1048576).toFixed(2)} MB  (${((Date.now() - t) / 1000).toFixed(1)}s)`);
}
GENJS

cat > "$SPIKE/gen-samples.py" <<'GENPY'
# Fallback generator (python3). usage: python3 gen-samples.py <outDir> [mb,mb,...]
import json, os, sys, time

out_dir = sys.argv[1]
sizes = (sys.argv[2] if len(sys.argv) > 2 else "2,10,50").split(",")
os.makedirs(out_dir, exist_ok=True)


def record(i):
    return {
        "id": "ID%d" % (1000000 + i),
        "hotel_id": i % 99991,
        "name": "Hotel %d 海景房 Seaview" % (i % 9973),
        "price": 100 + (i % 900) + (i % 7) / 10,
        "currency": "CNY",
        "rating": (i % 50) / 10,
        "city": "City%d" % (i % 317),
        "address": "Aabaadhee Hingun Road %d" % i,
        "tags": ["tag%d" % (i % 13), "tag%d" % (i % 7), "tag%d" % (i % 101)],
        "active": i % 3 == 0,
        "desc": "描述文本 description %d" % i,
        "updated": "2026-0%d-1%d" % (1 + (i % 9), i % 9),
    }


for mb in sizes:
    target = int(float(mb) * 1048576)
    path = os.path.join(out_dir, "%smb.json" % mb)
    started = time.time()
    written = 0
    i = 0
    with open(path, "w", encoding="utf-8") as fh:
        head = '{"status":{"code":0,"msg":"SUCCESS"},"data":{"items":['
        fh.write(head)
        written += len(head)
        first = True
        while written < target:
            piece = ("" if first else ",") + json.dumps(record(i), ensure_ascii=False)
            first = False
            fh.write(piece)
            written += len(piece.encode("utf-8"))
        fh.write("]}}")
    print("%smb.json  %.2f MB  (%.1fs)" % (mb, os.path.getsize(path) / 1048576, time.time() - started))
GENPY

